pub fn fibonacci(n: u32) -> u64 {
    match n {
        0 => 0,
        1 => 1,
        _ => fibonacci(n - 1) + fibonacci(n - 2),
    }
}

pub fn classify_number(n: i32) -> &'static str {
    match n {
        x if x > 0 => "positive",
        x if x < 0 => "negative",
        _ => "zero",
    }
}

pub fn sum_evens(n: u32) -> u32 {
    (1..=n).filter(|x| x % 2 == 0).sum()
}

pub fn describe_shape(width: f64, height: f64, kind: &str) -> String {
    match kind {
        "circle" => format!("Circle with radius {}", width),
        "rectangle" => format!("Rectangle {}x{}", width, height),
        "triangle" => format!("Triangle with base {} and height {}", width, height),
        _ => format!("Unknown shape: {}", kind),
    }
}

