use std::num::ParseIntError;

#[derive(Debug)]
pub enum AppError {
    ParseError(ParseIntError),
    NotFound(String),
    DivisionByZero,
}

impl From<ParseIntError> for AppError {
    fn from(e: ParseIntError) -> Self { AppError::ParseError(e) }
}

impl std::fmt::Display for AppError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            AppError::ParseError(e) => write!(f, "Parse error: {}", e),
            AppError::NotFound(s) => write!(f, "Not found: {}", s),
            AppError::DivisionByZero => write!(f, "Division by zero"),
        }
    }
}

impl std::error::Error for AppError {}

pub fn parse_and_divide(input: &str, divisor: i32) -> Result<i32, AppError> {
    let n: i32 = input.parse()?;
    if divisor == 0 { return Err(AppError::DivisionByZero); }
    Ok(n / divisor)
}

pub fn find_first_even(numbers: &[i32]) -> Option<i32> {
    numbers.iter().find(|&&n| n % 2 == 0).copied()
}

pub fn collect_results(items: Vec<Result<i32, AppError>>) -> Result<Vec<i32>, AppError> {
    items.into_iter().collect()
}
